+        .create();
+
+    TypeAdapter<?> adapter = gson.getAdapter(requestedType);
+    assertNotNull(adapter);
+    // Should be the same adapter instance the concurrent thread received
+    assertSame(threadAdapter.get(), adapter);
+  }
