+    public Type getType(String methodName) {
+        Method method;
+        try {
+            method = getClass().getDeclaredMethod(methodName, new Class<?>[]{});
+        } catch (Exception e) {
+            throw new IllegalStateException(e);
+        }
+        Type gtype = method.getGenericReturnType();
+        return gtype;
+    }
