+        executor = new ThreadPoolExecutor(100, 200, 10, TimeUnit.SECONDS,
+            new ArrayBlockingQueue<Runnable>(10000), new ThreadFactoryImpl("testMultiThread"));
+        for (int i = 0; i < 10000; i++) {
