+        this.incPutMessageEntireTime(value);
         final LongAdder[] times = this.putMessageDistributeTime;

         if (null == times)
@@ -443,6 +511,8 @@ public HashMap<String, String> getRuntimeInfo() {
         result.put("getMissTps", this.getGetMissTps());
