+        assertSame(name1, PropertyName.merge(name1, empty));
+        assertSame(name1, PropertyName.merge(empty, name1));
+
+        assertEquals(PropertyName.construct("name1", "nsX"),
+                PropertyName.merge(nsX, name1));
+    }
+}

