+        Predicate<String> mock = Mockito.mock(Predicate.class);
+        ProductionCode.simpleMethod(mock, "parameter");
+        verify(mock).test(captor.capture());
+        assertThat(captor.getValue()).isEqualTo("parameter");
+    }
 }

