+
+        BigDecimal biggie = objectMapper.readValue("423451233", BigDecimal.class);
+        assertEquals(BigDecimal.valueOf(423451233.0d), biggie);
+    }
+
+    private void _verifyCoerceFail(ObjectMapper m, Class<?> targetType,
