+        ObjectMapper mapper = new ObjectMapper().configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
+        mapper.readerForUpdating(root).readValue("{\"child\": null }");
+        assertTrue(root.child == null);
+    }
+
